"""Write docs/REPRODUCIBILITY.md from the experiment records (measured wall-clock, versions, hardware)."""

from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def main() -> None:
    recs = sorted((ROOT / "results").glob("*/record.json"))
    lines = [
        "# Reproducibility",
        "",
        "<!-- generated by scripts/make_reproducibility.py from results/*/record.json -->",
        "",
        "One command reproduces every reported result (quick profile):",
        "",
        "```bash",
        "python scripts/reproduce_all.py --profile quick",
        "```",
        "",
        "Each experiment writes `results/<id>/` with `record.json` (all spec Section 13 fields, including the "
        "hypothesis written before the run, seed, git commit, software versions and hardware), `config.yaml` "
        "where applicable, `metrics.json`, `history.csv` and `git_hash.txt`. Pinned versions: `constraints.txt`.",
        "",
        "## Measured wall-clock times (build machine, quick profile)",
        "",
        "| experiment | status | wall clock [s] | seed | git commit | reproduce |",
        "|---|---|---|---|---|---|",
    ]
    hw = None
    for r in recs:
        d = json.loads(r.read_text())
        hw = hw or d.get("hardware")
        wc = d.get("results", {}).get("wall_clock_s")
        lines.append(
            f"| {d['experiment_id']} | {d['status']} | {wc:.0f} | {d['seed']} | `{d['git_commit'][:10]}` | "
            f"`{d['reproducibility']}` |"
            if wc is not None
            else f"| {d['experiment_id']} | {d['status']} | n/a | {d['seed']} | `{d['git_commit'][:10]}` | "
            f"`{d['reproducibility']}` |"
        )
    if hw:
        lines += ["", "## Hardware and software of the build machine", "", "```json", json.dumps(hw, indent=1), "```"]
    lines += [
        "",
        "Notes: several studies shared the 4 CPU cores concurrently, so wall-clock times are upper bounds "
        "for an idle machine. GPU was not available. Colab/Kaggle notebooks in `notebooks/` were generated "
        "but not executed. Determinism: seeds fixed; CPU runs are bit-reproducible "
        "(tests/test_ml.py::test_determinism_and_serialisation, tests/test_validation_engine.py).",
    ]
    (ROOT / "docs" / "REPRODUCIBILITY.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(f"{len(recs)} records")


if __name__ == "__main__":
    main()
